type FocusableWorkspaceProps = {
  focusedRecordId?: string | null;
  onFocusedRecordHandled?: () => void;
};

function useFocusedRecord<T extends { id: string }>(
  records: T[],
  focusedRecordId: string | null | undefined,
  onFocusedRecordHandled: (() => void) | undefined,
  applyRecord: (record: T) => void,
) {
  useEffect(() => {
    if (!focusedRecordId) return;
    const record = records.find((item) => item.id === focusedRecordId);
    if (!record) return;
    applyRecord(record);
    onFocusedRecordHandled?.();
  }, [applyRecord, focusedRecordId, onFocusedRecordHandled, records]);
}

