const actionPriorityVariant = (priority: number) =>
  priority <= 2 ? "destructive" : priority <= 6 ? "outline" : "secondary";

type BadgeVariant = "default" | "secondary" | "destructive" | "outline";

const progressPercent = (complete: number, total: number) => {
  if (total <= 0) return 0;
  return Math.max(0, Math.min(100, Math.round((complete / total) * 100)));
};

const designCollectionLabel = (collection: DesignActionItem["collection"]) =>
  collection === "branding" ? "Branding" : collection === "colorPalettes" ? "Palette" : "Typography";

const systemCollectionLabel = (collection: SystemActionItem["collection"]) =>
  collection === "systemBackups"
    ? "Backups"
    : collection === "systemUsers"
      ? "Users"
      : collection === "security"
        ? "Security"
        : collection === "documentation"
          ? "Docs"
          : "Settings";

function DesignActionQueuePanel({
  actions,
  onOpen,
}: {
  actions: DesignActionItem[];
  onOpen: (action: DesignActionItem) => void;
}) {
  return (
    <div className="rounded-md border bg-white p-3">
      <div className="flex flex-wrap items-center justify-between gap-2">
        <div>
          <div className="text-sm font-semibold">Design Action Queue</div>
          <div className="mt-1 text-xs text-muted-foreground">
            {actions.length > 0
              ? `${actions.length} design record${actions.length === 1 ? "" : "s"} need cleanup.`
              : "No design cleanup is queued."}
          </div>
        </div>
        <Badge variant={actions.length > 0 ? "destructive" : "secondary"}>{actions.length}</Badge>
      </div>
      <div className="mt-3 space-y-2">
        {actions.slice(0, 4).map((action) => (
          <div key={`${action.collection}-${action.id}`} className="rounded-md border bg-muted/20 p-3 text-sm">
            <div className="flex flex-wrap items-start justify-between gap-3">
              <div className="min-w-0 flex-1">
                <div className="truncate font-semibold">{action.name}</div>
                <div className="mt-1 truncate text-xs text-muted-foreground">
                  {designCollectionLabel(action.collection)}
                  {action.isActive === null ? "" : ` · ${action.isActive ? "active" : "inactive"}`}
                </div>
                <div className="mt-1 text-xs text-muted-foreground">Next: {action.nextAction}</div>
              </div>
              <div className="flex shrink-0 flex-wrap justify-end gap-1">
                <Badge variant={actionPriorityVariant(action.priority)}>{action.priorityLabel}</Badge>
                <Badge variant="outline">{action.issueCount}</Badge>
              </div>
            </div>
            <div className="mt-3">
              <Button type="button" size="sm" variant="outline" onClick={() => onOpen(action)}>
                Open
              </Button>
            </div>
          </div>
        ))}
        {actions.length === 0 && (
          <p className="rounded-md border border-dashed p-3 text-xs text-muted-foreground">
            Branding, palette, and typography readiness are clear.
          </p>
        )}
      </div>
    </div>
  );
}

