function normalizeAdminToolKey(toolKey: string | null | undefined) {
  return allTools.some((tool) => tool.key === toolKey) ? toolKey! : "overview";
}

function getInitialAdminToolKey() {
  if (typeof window === "undefined") return "overview";
  return normalizeAdminToolKey(new URLSearchParams(window.location.search).get("tool"));
}

function getInitialFocusedCmsRecord() {
  if (typeof window === "undefined") return null;
  const params = new URLSearchParams(window.location.search);
  const toolKey = normalizeAdminToolKey(params.get("tool"));
  const id = params.get("record");

  return id && collectionTools.some((tool) => tool.key === toolKey) ? { toolKey, id } : null;
}

function getInitialFocusedLeadId() {
  if (typeof window === "undefined") return null;
  const params = new URLSearchParams(window.location.search);
  const toolKey = normalizeAdminToolKey(params.get("tool"));
  const leadId = params.get("lead");

  return leadId && (toolKey === "crmPipeline" || toolKey === "crmLeads") ? leadId : null;
}

const defaultPipelineStages = ["new", "contacted", "estimate", "won", "lost"];
const defaultSiteMarket = "Greater Charlotte area";
const defaultSiteBusinessHours = "Mon-Sat: 7am - 6pm";
const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

const formatPipelineStageLabel = (stage: string) =>
  stage
    .split(/[-_\s]+/)
    .filter(Boolean)
    .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
    .join(" ");

const formatCmsBlockTypeLabel = (type: string) =>
  formatPipelineStageLabel(type.replace(/([a-z])([A-Z])/g, "$1-$2"));

const formatPrimaryRouteLaunchSummary = (result: PrimaryRouteLaunchResult) =>
  `CMS route launch pass complete: ${result.totals.published} published, ${result.totals.alreadyLive} already live, ${result.totals.created} created, ${result.totals.repaired} repaired, ${result.mediaImport.imported} referenced asset${result.mediaImport.imported === 1 ? "" : "s"} imported${result.mediaImport.missing > 0 ? `, ${result.mediaImport.missing} missing` : ""}${result.totals.blocked > 0 ? `, ${result.totals.blocked} blocked` : ""}${result.safetyBackup ? `, safety backup created: ${result.safetyBackup.name}` : ""}.`;

const getPrimaryRouteLaunchIssueOutcomes = (result: PrimaryRouteLaunchResult | null) =>
  result?.outcomes.filter((outcome) => outcome.action === "blocked" || outcome.issues.length > 0) ?? [];

const formatLeadAge = (createdAt: Date | string) => {
  const created = new Date(createdAt);
  const diffMs = Date.now() - created.getTime();
  const diffHours = Math.max(0, Math.floor(diffMs / 36e5));
  if (diffHours < 1) return "New";
  if (diffHours < 24) return `${diffHours}h old`;
  const diffDays = Math.floor(diffHours / 24);
  return `${diffDays}d old`;
};

const leadAgeHours = (date: Date | string) =>
  Math.max(0, Math.floor((Date.now() - new Date(date).getTime()) / 36e5));

const formatLeadHours = (hours: number) => {
  if (hours < 1) return "current";
  if (hours < 24) return `${hours}h`;
  return `${Math.floor(hours / 24)}d`;
};

const leadPriorityLabel = (priority?: string | null) =>
  priority === "high" ? "High" : priority === "low" ? "Low" : "Normal";

const leadNextFollowUpLabel = (lead: CrmLead) => {
  if (!lead.nextFollowUpAt) return "No scheduled follow-up";
  const followUpDate = new Date(lead.nextFollowUpAt);
  const label = followUpDate.toLocaleString(undefined, { month: "short", day: "numeric", hour: "numeric", minute: "2-digit" });
  return followUpDate.getTime() <= Date.now() ? `Due ${label}` : `Scheduled ${label}`;
};

const dateTimeLocalValue = (value?: Date | string | null) => {
  if (!value) return "";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return "";
  const local = new Date(date.getTime() - date.getTimezoneOffset() * 60000);
  return local.toISOString().slice(0, 16);
};

const leadDraftPayload = (draft: LeadDraft) => {
  const followUpDate = draft.nextFollowUpAt ? new Date(draft.nextFollowUpAt) : null;

  return {
    name: draft.name.trim(),
    email: draft.email.trim(),
    phone: draft.phone.trim(),
    service: draft.service.trim(),
    message: draft.message.trim(),
    status: draft.status.trim(),
    pipelineStage: draft.pipelineStage.trim(),
    priority: draft.priority.trim(),
    nextFollowUpAt: followUpDate && !Number.isNaN(followUpDate.getTime()) ? followUpDate.toISOString() : null,
    notes: draft.notes.trim(),
    assignedTo: draft.assignedTo.trim(),
  };
};

const leadDraftReadinessIssues = (
  draft: LeadDraft,
  pipelineStages: string[],
  activeAssigneeIds: Set<string>,
  requireMessage = false,
) => {
  const issues: string[] = [];
  const name = draft.name.trim();
  const email = draft.email.trim();
  const phone = draft.phone.trim();
  const pipelineStage = draft.pipelineStage.trim();
  const status = draft.status.trim();
  const priority = draft.priority.trim();
  const assignedTo = draft.assignedTo.trim();

  if (!name) issues.push("Lead name is required.");
  if (!email && !phone) issues.push("Email or phone is required.");
  if (requireMessage && !draft.message.trim()) issues.push("Project details are required.");
  if (!pipelineStage) {
    issues.push("Pipeline stage is required.");
  } else if (!pipelineStages.includes(pipelineStage)) {
    issues.push(`Pipeline stage "${pipelineStage}" is not configured.`);
  }
  if (!status) {
    issues.push("Lead status is required.");
  } else if (!crmLeadStatuses.has(status)) {
    issues.push(`Lead status "${status}" is not supported.`);
  }
  if (!priority) {
    issues.push("Lead priority is required.");
  } else if (!crmLeadPriorities.has(priority)) {
    issues.push(`Lead priority "${priority}" is not supported.`);
  }
  if (draft.nextFollowUpAt && Number.isNaN(new Date(draft.nextFollowUpAt).getTime())) {
    issues.push("Next follow-up date is invalid.");
  }
  if (assignedTo && !activeAssigneeIds.has(assignedTo)) {
    issues.push("Assigned user must be an active system user.");
  }

  return issues;
};

const needsLeadFollowUp = (lead: CrmLead) => {
  if (lead.pipelineStage === "won" || lead.pipelineStage === "lost" || lead.status === "closed") {
    return false;
  }

  if (lead.nextFollowUpAt && new Date(lead.nextFollowUpAt).getTime() <= Date.now()) {
    return true;
  }

  const hoursSinceUpdate = leadAgeHours(lead.updatedAt);
  if (lead.pipelineStage === "new") return hoursSinceUpdate >= 4;
  if (lead.pipelineStage === "contacted") return hoursSinceUpdate >= 24;
  if (lead.pipelineStage === "estimate") return hoursSinceUpdate >= 48;
  return hoursSinceUpdate >= 72;
};

const leadIsOpen = (lead: CrmLead) =>
  lead.pipelineStage !== "won" && lead.pipelineStage !== "lost" && lead.status !== "closed";

const getLeadFollowUpLabel = (lead: CrmLead) => {
  if (lead.nextFollowUpAt && new Date(lead.nextFollowUpAt).getTime() <= Date.now()) return leadNextFollowUpLabel(lead);
  if (lead.pipelineStage === "new") return "Initial outreach needed";
  if (lead.pipelineStage === "contacted") return "Follow up after first contact";
  if (lead.pipelineStage === "estimate") return "Check estimate decision";
  if (lead.pipelineStage === "won") return "Won project";
  if (lead.pipelineStage === "lost") return "Lost opportunity";
  return "Review next step";
};

const leadFollowUpSortTime = (lead: CrmLead) => {
  const scheduledTime = lead.nextFollowUpAt ? new Date(lead.nextFollowUpAt).getTime() : Number.NaN;
  if (Number.isFinite(scheduledTime)) return scheduledTime;
  return new Date(lead.updatedAt).getTime();
};

const leadNotesLines = (lead: CrmLead) =>
  (lead.notes ?? "")
    .split("\n")
    .map((line) => line.trim())
    .filter(Boolean);

const getLeadActivityLines = (lead: CrmLead) =>
  leadNotesLines(lead)
    .filter((line) => /^\[[^\]]+\]/.test(line))
    .reverse();

const getLeadSourceDetails = (lead: CrmLead) => {
  const lines = leadNotesLines(lead);
  const page = lines.find((line) => line.toLowerCase().startsWith("page:"))?.replace(/^page:\s*/i, "").trim() ?? "";
  const referrer = lines.find((line) => line.toLowerCase().startsWith("referrer:"))?.replace(/^referrer:\s*/i, "").trim() ?? "";
  const landingPage = lines.find((line) => line.toLowerCase().startsWith("landing page:"))?.replace(/^landing page:\s*/i, "").trim() ?? "";
  const landingReferrer = lines
    .find((line) => line.toLowerCase().startsWith("landing referrer:"))
    ?.replace(/^landing referrer:\s*/i, "")
    .trim() ?? "";
  const tracking = lines.filter((line) =>
    /^(utm source|utm medium|utm campaign|utm term|utm content|google click id|facebook click id):\s*/i.test(line),
  );
  const landingTracking = lines.filter((line) =>
    /^landing (utm source|utm medium|utm campaign|utm term|utm content|google click id|facebook click id):\s*/i.test(line),
  );
  const fields = lines.filter((line) =>
    !/^page:\s*/i.test(line) &&
    !/^referrer:\s*/i.test(line) &&
    !/^landing page:\s*/i.test(line) &&
    !/^landing referrer:\s*/i.test(line) &&
    !tracking.includes(line) &&
    !landingTracking.includes(line) &&
    !/^\[[^\]]+\]/.test(line),
  );
  return { page, referrer, landingPage, landingReferrer, tracking, landingTracking, fields };
};

const leadAttributionFilterLabel = (value: string) => {
  if (value === "direct") return "Direct / no referrer";
  return value.length > 46 ? `${value.slice(0, 43)}...` : value;
};

const leadPriorityScore = (lead: CrmLead) => {
  if (lead.pipelineStage === "won" || lead.pipelineStage === "lost" || lead.status === "closed") return 0;
  const hoursSinceUpdate = leadAgeHours(lead.updatedAt);
  const priorityWeight = lead.priority === "high" ? 250 : lead.priority === "low" ? -100 : 0;
  if (needsLeadFollowUp(lead)) return 1000 + priorityWeight + hoursSinceUpdate;
  if (lead.pipelineStage === "new") return 700 + priorityWeight + hoursSinceUpdate;
  if (lead.pipelineStage === "contacted") return 500 + priorityWeight + hoursSinceUpdate;
  if (lead.pipelineStage === "estimate") return 400 + priorityWeight + hoursSinceUpdate;
  return priorityWeight + hoursSinceUpdate;
};

const compareLeadsByPriority = (a: CrmLead, b: CrmLead) => {
  const scoreDelta = leadPriorityScore(b) - leadPriorityScore(a);
  if (scoreDelta !== 0) return scoreDelta;
  return new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime();
};

const compareFollowUpLeads = (a: CrmLead, b: CrmLead) => {
  const dueDelta = leadFollowUpSortTime(a) - leadFollowUpSortTime(b);
  if (dueDelta !== 0) return dueDelta;
  return compareLeadsByPriority(a, b);
};

const leadCreatedToday = (lead: CrmLead) => {
  const created = new Date(lead.createdAt);
  const today = new Date();
  return created.toDateString() === today.toDateString();
};

const formatPhoneDisplay = (value: string) => {
  const digits = value.replace(/\D/g, "");
  if (digits.length === 10) {
    return `(${digits.slice(0, 3)}) ${digits.slice(3, 6)}-${digits.slice(6)}`;
  }
  return value;
};

const normalizedLeadEmail = (lead: Pick<CrmLead, "email">) => lead.email?.trim().toLowerCase() || "";

const normalizedLeadPhone = (lead: Pick<CrmLead, "phone">) => {
  const raw = lead.phone?.replace(/\D/g, "") ?? "";
  return raw.length === 11 && raw.startsWith("1") ? raw.slice(1) : raw;
};

const leadDuplicateContactKeys = (lead: Pick<CrmLead, "email" | "phone">) => [
  normalizedLeadEmail(lead) ? `email:${normalizedLeadEmail(lead)}` : "",
  normalizedLeadPhone(lead) ? `phone:${normalizedLeadPhone(lead)}` : "",
].filter(Boolean);

const crmLeadStatuses = new Set(["new", "open", "quoted", "closed"]);
const crmLeadPriorities = new Set(["low", "normal", "high"]);
const nonConvertibleFormSubmissionStatuses = new Set(["lead-created", "reviewed", "archived", "spam"]);

const leadsShareDuplicateContact = (
  a: Pick<CrmLead, "email" | "phone">,
  b: Pick<CrmLead, "email" | "phone">,
) => {
  const bKeys = new Set(leadDuplicateContactKeys(b));
  return leadDuplicateContactKeys(a).some((key) => bKeys.has(key));
};

const duplicateLeadContactIds = (leads: CrmLead[]) => {
  const contactMap = new Map<string, string[]>();
  leads.forEach((lead) => {
    leadDuplicateContactKeys(lead).forEach((key) => {
      contactMap.set(key, [...(contactMap.get(key) ?? []), lead.id]);
    });
  });

  return new Set(
    Array.from(contactMap.values())
      .filter((ids) => ids.length > 1)
      .flat(),
  );
};

const leadContactSummary = (lead: CrmLead) => lead.phone || lead.email || "No contact info";

const getPipelineStagesFromSettings = (settings: CmsSetting[]) => {
  const configuredStages = settings.find((setting) => setting.key === "site")?.value.leadPipelineStages;
  if (!Array.isArray(configuredStages)) return defaultPipelineStages;

  const stages = configuredStages.map((stage) => String(stage).trim()).filter(Boolean);
  return stages.length > 0 ? Array.from(new Set(stages)) : defaultPipelineStages;
};

const getPipelineStagesFromValue = (value: Record<string, unknown>) => {
  const configuredStages = value.leadPipelineStages;
  if (!Array.isArray(configuredStages)) return defaultPipelineStages;

  const stages = configuredStages.map((stage) => String(stage).trim()).filter(Boolean);
  return stages.length > 0 ? Array.from(new Set(stages)) : defaultPipelineStages;
};

const pagePreviewUrl = (slug: string) => {
  if (slug === "home") return "/";
  if (slug === "about" || slug === "contact" || slug === "gallery" || slug === "services" || slug.startsWith("services/")) {
    return `/${slug}`;
  }
  if (slug === "blog") return "/blog";
  return `/${slug.split("/").map((part) => encodeURIComponent(part)).join("/")}`;
};

const withCmsPreviewParam = (path: string, enabled: boolean) => {
  const [pathWithoutHash, hashFragment] = path.split("#", 2);
  const [pathname, query = ""] = pathWithoutHash.split("?", 2);
  const params = new URLSearchParams(query);
  params.set("cms-preview", enabled ? "1" : "0");
  const queryString = params.toString();

  return `${pathname || "/"}${queryString ? `?${queryString}` : ""}${hashFragment ? `#${hashFragment}` : ""}`;
};

const primaryCmsRouteSlugs = [
  "home",
  "services",
  "about",
  "contact",
  "gallery",
  "blog",
  "services/frameless-showers",
  "services/window-installation",
  "services/door-installation",
  "services/window-repair",
  "services/commercial-glass",
  "services/showers",
  "services/windows",
  "services/doors",
] as const;
const primaryCmsRouteSlugSet = new Set<string>(primaryCmsRouteSlugs);
const publicCmsVisualParityRouteStatuses = new Set(["approved", "changes-needed"]);

type PublicCmsVisualParityRouteReview = {
  slug: string;
  path: string;
  reviewedAt: string;
  status?: string;
  notes?: string;
};

function normalizePublicCmsVisualParityRouteReviews(value: unknown): PublicCmsVisualParityRouteReview[] {
  if (!Array.isArray(value)) return [];

  const reviews = new Map<string, PublicCmsVisualParityRouteReview>();
  value.forEach((item) => {
    if (!item || Array.isArray(item) || typeof item !== "object") return;
    const record = item as Record<string, unknown>;
    const slug = typeof record.slug === "string" ? record.slug.trim() : "";
    const reviewedAt = typeof record.reviewedAt === "string" && !Number.isNaN(Date.parse(record.reviewedAt))
      ? new Date(record.reviewedAt).toISOString()
      : "";
    if (!slug || !primaryCmsRouteSlugSet.has(slug) || !reviewedAt) return;

    reviews.set(slug, {
      slug,
      path: typeof record.path === "string" && record.path.trim() ? record.path.trim() : pagePreviewUrl(slug),
      reviewedAt,
      status:
        typeof record.status === "string" && publicCmsVisualParityRouteStatuses.has(record.status.trim())
          ? record.status.trim()
          : "approved",
      ...(typeof record.notes === "string" && record.notes.trim() ? { notes: record.notes.trim() } : {}),
    });
  });

  return primaryCmsRouteSlugs
    .map((slug) => reviews.get(slug))
    .filter((review): review is PublicCmsVisualParityRouteReview => Boolean(review));
}

function publicCmsVisualParityRouteReviewIssues(value: unknown) {
  const issues: string[] = [];
  if (value === undefined || value === null || value === "") return issues;
  if (!Array.isArray(value)) return ["Site setting publicCmsVisualParityRouteReviews must be an array."];

  value.forEach((item, index) => {
    if (!item || Array.isArray(item) || typeof item !== "object") {
      issues.push(`Visual parity route review ${index + 1} must be an object.`);
      return;
    }
    const record = item as Record<string, unknown>;
    const slug = typeof record.slug === "string" ? record.slug.trim() : "";
    if (!slug || !primaryCmsRouteSlugSet.has(slug)) {
      issues.push(`Visual parity route review ${index + 1} must use a primary route slug.`);
    }
    if (typeof record.reviewedAt !== "string" || Number.isNaN(Date.parse(record.reviewedAt))) {
      issues.push(`Visual parity route review ${index + 1} needs a valid reviewedAt timestamp.`);
    }
    if (
      typeof record.status === "string" &&
      record.status.trim() &&
      !publicCmsVisualParityRouteStatuses.has(record.status.trim())
    ) {
      issues.push(`Visual parity route review ${index + 1} status must be approved or changes-needed.`);
    }
  });

  return issues;
}

const blogPostPreviewUrl = (slug: string) => `/blog/${encodeURIComponent(slug)}`;

const getPageSlugRouteIssue = (slug: string) => {
  const cleanSlug = slug.trim().replace(/^\/+|\/+$/g, "").toLowerCase();
  const [root] = cleanSlug.split("/");
  if (!cleanSlug) return "Slug is required before publishing.";
  if (["admin", "api", "assets", "cms-assets", "images", "page"].includes(root)) {
    return `The "${root}" path is reserved for system routes or static assets.`;
  }
  if (root === "blog" && cleanSlug !== "blog") {
    return "Use Blog Posts for /blog/... URLs instead of CMS Pages.";
  }
  return "";
};

const cmsHrefSafetyIssue = (label: string, href: unknown) => {
  if (typeof href !== "string" || !href.trim()) return "";
  return safeCmsHref(href)
    ? ""
    : `${label} uses an unsafe URL. Use a site path, #anchor, http(s), mailto, or tel link.`;
};

const cmsAssetUrlSafetyIssue = (label: string, url: unknown) => {
  if (typeof url !== "string" || !url.trim()) return "";
  return safeCmsAssetUrl(url)
    ? ""
    : `${label} uses an unsafe asset URL. Use a site asset path or http(s) URL.`;
};

const normalizedLocalCmsAssetPath = (url: unknown) => {
  const safeUrl = typeof url === "string" ? safeCmsAssetUrl(url) : "";
  if (!safeUrl || !safeUrl.startsWith("/") || safeUrl.startsWith("//")) return "";
  return safeUrl.split(/[?#]/)[0];
};

const mediaLibraryHasLocalAsset = (mediaItems: CmsMedia[], url: unknown) => {
  const path = normalizedLocalCmsAssetPath(url);
  if (!path) return true;
  return mediaItems.some((media) => normalizedLocalCmsAssetPath(media.url) === path);
};

const cmsMediaLibraryIssue = (label: string, url: unknown, mediaItems: CmsMedia[]) => {
  const path = normalizedLocalCmsAssetPath(url);
  if (!path || mediaLibraryHasLocalAsset(mediaItems, path)) return "";
  return `${label} uses a local asset that is not registered in Media. Use Import Assets or select a saved Media record.`;
};

const hasMediaRegistrationIssue = (issues: Array<{ message: string }> | string[]) =>
  issues.some((issue) => (typeof issue === "string" ? issue : issue.message).includes("not registered in Media"));

const cmsLegacyAssetIssue = (label: string, url: unknown) =>
  typeof url === "string" && url.includes("/images/gallery/frameless-showers/")
    ? `${label} uses a legacy starter image path. Use /cms-assets/... or select media from the Media workspace.`
    : "";

const cmsHtmlSafetyIssue = (label: string, html: unknown) => {
  if (typeof html !== "string" || !html.trim()) return "";
  return sanitizeCmsHtml(html) === html
    ? ""
    : `${label} includes HTML that will be stripped from the public site.`;
};

function getBrandingDraftIssues(draft: BrandingDraft, mediaItems: CmsMedia[] = []) {
  const issues: string[] = [];
  const socialLinks: Record<string, string> = {};
  const logoIssue =
    cmsAssetUrlSafetyIssue("Logo URL", draft.logoUrl) ||
    cmsLegacyAssetIssue("Logo URL", draft.logoUrl);
  const faviconIssue =
    cmsAssetUrlSafetyIssue("Favicon URL", draft.faviconUrl) ||
    cmsLegacyAssetIssue("Favicon URL", draft.faviconUrl);
  const logoMediaIssue = logoIssue ? "" : cmsMediaLibraryIssue("Logo URL", draft.logoUrl, mediaItems);
  const faviconMediaIssue = faviconIssue ? "" : cmsMediaLibraryIssue("Favicon URL", draft.faviconUrl, mediaItems);

  if (!draft.siteName.trim()) issues.push("Site name is required.");
  if (logoIssue) issues.push(logoIssue);
  if (faviconIssue) issues.push(faviconIssue);
  if (logoMediaIssue) issues.push(logoMediaIssue);
  if (faviconMediaIssue) issues.push(faviconMediaIssue);

  try {
    const parsed = JSON.parse(draft.socialLinksJson);
    if (!parsed || Array.isArray(parsed) || typeof parsed !== "object") {
      issues.push("Social links must be a JSON object.");
    } else {
      Object.entries(parsed as Record<string, unknown>).forEach(([label, href]) => {
        const cleanLabel = label.trim();
        if (!cleanLabel) {
          issues.push("Social link labels are required.");
        }
        if (typeof href !== "string") {
          issues.push(`Social link "${cleanLabel || label}" must be a URL string.`);
          return;
        }
        const cleanHref = href.trim();
        if (!cleanHref) {
          issues.push(`Social link "${cleanLabel || label}" must include a URL.`);
          return;
        }
        socialLinks[cleanLabel] = cleanHref;
        const hrefIssue = cmsHrefSafetyIssue(`Social link "${cleanLabel}"`, cleanHref);
        if (hrefIssue) issues.push(hrefIssue);
      });
    }
  } catch {
    issues.push("Social links must be valid JSON.");
  }

  return { issues, socialLinks };
}

function getSettingDraftIssues(draft: SettingDraft, currentSetting?: CmsSetting) {
  const issues: string[] = [];
  if (!draft.key.trim()) issues.push("Setting key is required.");
  if (currentSetting?.key === "site" && draft.key.trim() !== "site") {
    issues.push("The core site setting key cannot be renamed.");
  }

  let value: unknown;
  try {
    value = JSON.parse(draft.valueJson);
  } catch {
    issues.push("Setting value must be valid JSON.");
    return { issues, value: {} as Record<string, unknown> };
  }

  if (!value || Array.isArray(value) || typeof value !== "object") {
    issues.push("Setting value must be a JSON object.");
    return { issues, value: {} as Record<string, unknown> };
  }

  const recordValue = value as Record<string, unknown>;
  if (draft.key.trim() === "site") {
    if (typeof recordValue.businessName !== "string" || !recordValue.businessName.trim()) {
      issues.push("Site setting needs a businessName value.");
    }
    if ("siteUrl" in recordValue) {
      if (typeof recordValue.siteUrl !== "string") {
        issues.push("Site setting siteUrl must be a text value.");
      } else if (recordValue.siteUrl.trim()) {
        try {
          const parsed = new URL(recordValue.siteUrl);
          if (parsed.protocol !== "http:" && parsed.protocol !== "https:") {
            issues.push("Site setting siteUrl must be an http or https URL.");
          }
        } catch {
          issues.push("Site setting siteUrl must be a valid URL.");
        }
      }
    }
    if ("market" in recordValue && typeof recordValue.market !== "string") {
      issues.push("Site setting market must be a text value.");
    }
    if ("businessHours" in recordValue && typeof recordValue.businessHours !== "string") {
      issues.push("Site setting businessHours must be a text value.");
    }
    if ("publicCmsEnabled" in recordValue && typeof recordValue.publicCmsEnabled !== "boolean") {
      issues.push("Site setting publicCmsEnabled must be true or false.");
    }
    if (
      "publicCmsVisualParityApprovedAt" in recordValue &&
      recordValue.publicCmsVisualParityApprovedAt !== null &&
      recordValue.publicCmsVisualParityApprovedAt !== ""
    ) {
      if (
        typeof recordValue.publicCmsVisualParityApprovedAt !== "string" ||
        Number.isNaN(Date.parse(recordValue.publicCmsVisualParityApprovedAt))
      ) {
        issues.push("Site setting publicCmsVisualParityApprovedAt must be a valid timestamp or blank.");
      }
      const reviewedRoutes = normalizePublicCmsVisualParityRouteReviews(recordValue.publicCmsVisualParityRouteReviews);
      if (reviewedRoutes.length < primaryCmsRouteSlugs.length || reviewedRoutes.some((review) => review.status !== "approved")) {
        issues.push("Approve every primary route in publicCmsVisualParityRouteReviews before approving CMS visual parity.");
      }
    }
    issues.push(...publicCmsVisualParityRouteReviewIssues(recordValue.publicCmsVisualParityRouteReviews));
    if (!Array.isArray(recordValue.leadPipelineStages)) {
      issues.push("Site setting leadPipelineStages must be an array.");
    } else {
      const stages = recordValue.leadPipelineStages.map((stage) => String(stage).trim()).filter(Boolean);
      if (stages.length === 0) {
        issues.push("Site setting leadPipelineStages must include at least one stage.");
      }
      if (new Set(stages).size !== stages.length) {
        issues.push("Site setting leadPipelineStages must not include duplicates.");
      }
    }
  }

  return { issues, value: draft.key.trim() === "site" ? normalizeSiteSettingValueForSave(recordValue) : recordValue };
}

function normalizeSiteSettingValueForSave(value: Record<string, unknown>) {
  const allowedKeys = [
    "businessName",
    "siteUrl",
    "market",
    "businessHours",
    "publicCmsEnabled",
    "publicCmsVisualParityRouteReviews",
    "publicCmsVisualParityApprovedAt",
    "leadPipelineStages",
    "publicCmsLaunchConfirmedAt",
  ] as const;

  const next = allowedKeys.reduce((acc, key) => {
    if (key in value) {
      acc[key] = value[key];
    }
    return acc;
  }, {} as Record<string, unknown>);

  ["businessName", "market", "businessHours"].forEach((field) => {
    if (typeof next[field] === "string") next[field] = next[field].trim();
  });

  if (typeof next.siteUrl === "string") {
    const siteUrl = next.siteUrl.trim();
    if (siteUrl) {
      try {
        const parsed = new URL(siteUrl);
        next.siteUrl = parsed.protocol === "http:" || parsed.protocol === "https:"
          ? parsed.toString().replace(/\/$/, "")
          : siteUrl;
      } catch {
        next.siteUrl = siteUrl;
      }
    } else {
      next.siteUrl = "";
    }
  }

  if (Array.isArray(next.leadPipelineStages)) {
    const stages = next.leadPipelineStages.map((stage) => String(stage).trim()).filter(Boolean);
    next.leadPipelineStages = stages;
  }
  const routeReviews = normalizePublicCmsVisualParityRouteReviews(next.publicCmsVisualParityRouteReviews);
  if (routeReviews.length > 0) {
    next.publicCmsVisualParityRouteReviews = routeReviews;
  } else {
    delete next.publicCmsVisualParityRouteReviews;
  }
  if (
    typeof next.publicCmsVisualParityApprovedAt === "string" &&
    !Number.isNaN(Date.parse(next.publicCmsVisualParityApprovedAt))
  ) {
    next.publicCmsVisualParityApprovedAt = new Date(next.publicCmsVisualParityApprovedAt).toISOString();
  } else {
    delete next.publicCmsVisualParityApprovedAt;
  }
  next.publicCmsEnabled = next.publicCmsEnabled === true;

  return next;
}

const colorPaletteTokenFields = [
  { key: "primary", label: "Primary" },
  { key: "secondary", label: "Secondary" },
  { key: "accent", label: "Accent" },
  { key: "background", label: "Background" },
  { key: "foreground", label: "Foreground" },
] as const;

function isHslCssToken(value: unknown) {
  if (typeof value !== "string") return false;
  const match = value.trim().match(/^(\d+(?:\.\d+)?)\s+(\d+(?:\.\d+)?)%\s+(\d+(?:\.\d+)?)%$/);
  if (!match) return false;

  const [, hue, saturation, lightness] = match.map(Number);
  return hue >= 0 && hue <= 360 && saturation >= 0 && saturation <= 100 && lightness >= 0 && lightness <= 100;
}

function getColorPaletteDraftIssues(draft: ColorPaletteDraft) {
  const issues: string[] = [];
  if (!draft.name.trim()) issues.push("Palette name is required.");

  colorPaletteTokenFields.forEach((field) => {
    if (!isHslCssToken(draft[field.key])) {
      issues.push(`${field.label} must be an HSL token like "195 75% 38%".`);
    }
  });

  return issues;
}

function isSafeFontFamilyName(value: unknown) {
  return typeof value === "string" && /^[A-Za-z0-9][A-Za-z0-9 -]{0,79}$/.test(value.trim());
}

function safeFontFamilyStack(value: string, fallback: string) {
  const font = isSafeFontFamilyName(value) ? value.trim() : fallback;
  return `"${font}", sans-serif`;
}

function isSafeCssSizeValue(value: unknown) {
  return typeof value === "string" && /^(?:0|(?:\d+(?:\.\d+)?)(?:rem|em|px|%))$/.test(value.trim());
}

function safeCssSizeValue(value: unknown, fallback: string) {
  return isSafeCssSizeValue(value) ? String(value).trim() : fallback;
}

function getTypographyDraftIssues(draft: TypographyDraft) {
  const issues: string[] = [];
  if (!draft.name.trim()) issues.push("Typography name is required.");
  if (!isSafeFontFamilyName(draft.headingFont)) {
    issues.push("Heading font can only use letters, numbers, spaces, and hyphens.");
  }
  if (!isSafeFontFamilyName(draft.bodyFont)) {
    issues.push("Body font can only use letters, numbers, spaces, and hyphens.");
  }
  const scale = readJsonRecord(draft.scaleJson);
  ["h1", "h2", "h3", "body", "small"].forEach((key) => {
    if (scale[key] !== undefined && !isSafeCssSizeValue(scale[key])) {
      issues.push(`${key} scale must be a CSS size like "3rem", "18px", or "100%".`);
    }
  });
  return issues;
}

