const starterRouteSlugs = new Set([
  "home",
  "services",
  "about",
  "contact",
  "gallery",
  "blog",
  ...Object.keys(serviceStarterContent),
]);

const pageHasIndexableRouteContent = (page: CmsPage) =>
  starterRouteSlugs.has(page.slug) || page.content.sections.length > 0;

const pageIsPublicSitemapCandidate = (page: CmsPage) =>
  page.status === "published" && !page.seo.noIndex && pageHasIndexableRouteContent(page);

const postIsPublicSitemapCandidate = (post: CmsBlogPost) =>
  post.status === "published" && !post.seo.noIndex;

const pageStatuses = new Set(["draft", "published", "archived"]);

const pageSaveReadinessIssues = (draft: PageDraft): PageDependencyIssue[] => {
  const issues: PageDependencyIssue[] = [];
  const slug = draft.slug.trim();
  const status = draft.status.trim();

  if (!draft.title.trim()) {
    issues.push({ blockIndex: -1, blockType: "content", message: "Page title is required." });
  }
  if (!slug) {
    issues.push({ blockIndex: -1, blockType: "route", message: "Page slug is required." });
  } else {
    const slugRouteIssue = getPageSlugRouteIssue(slug);
    if (slugRouteIssue) {
      issues.push({ blockIndex: -1, blockType: "route", message: slugRouteIssue });
    }
  }
  if (status && !pageStatuses.has(status)) {
    issues.push({ blockIndex: -1, blockType: "content", message: `Page status "${draft.status}" is not supported.` });
  }
  if (draft.canonicalUrl.trim() && seoCanonicalIssue(draft.canonicalUrl)) {
    issues.push({ blockIndex: -1, blockType: "seo", message: "Canonical URL must be a valid http or https URL before saving." });
  }
  if (draft.ogImage.trim() && !safeCmsAssetUrl(draft.ogImage)) {
    issues.push({ blockIndex: -1, blockType: "seo", message: "OG image must use a safe site asset path or http(s) URL before saving." });
  }

  return issues;
};

type StarterIdentity = {
  siteName: string;
  market: string;
  siteUrl?: string;
};

const fallbackStarterIdentity: StarterIdentity = {
  siteName: "Glass & Door Pro",
  market: "greater Charlotte area",
};

function starterText(value: string, identity: StarterIdentity) {
  return value
    .replaceAll("Glass & Door Pro", identity.siteName)
    .replaceAll("the greater Charlotte, North Carolina area", identity.market)
    .replaceAll("greater Charlotte, North Carolina area", identity.market)
    .replaceAll("the greater Charlotte area", identity.market)
    .replaceAll("greater Charlotte area", identity.market)
    .replaceAll("Greater Charlotte area", identity.market)
    .replaceAll("Charlotte area", identity.market);
}

function starterValue(value: unknown, identity: StarterIdentity): unknown {
  if (typeof value === "string") return starterText(value, identity);
  if (Array.isArray(value)) return value.map((item) => starterValue(item, identity));
  if (value && typeof value === "object") {
    return Object.fromEntries(
      Object.entries(value as Record<string, unknown>).map(([key, entry]) => [key, starterValue(entry, identity)]),
    );
  }
  return value;
}

function brandStarterSections(sections: CmsSectionBlock[], identity: StarterIdentity) {
  return starterValue(sections, identity) as CmsSectionBlock[];
}

