  const extractReusableSection = useMutation({
    mutationFn: async () => {
      if (!selectedPage || !selectedSection) return null;
      const sectionTitle =
        typeof selectedSection.props?.title === "string" && selectedSection.props.title.trim()
          ? selectedSection.props.title.trim()
          : `${selectedPage.title} ${formatPipelineStageLabel(selectedSection.type)}`;
      const handleBase =
        slugifyText(`${selectedPage.slug}-${selectedSection.type}-${sectionTitle}`).slice(0, 56) ||
        `section-${Date.now()}`;
      const response = await apiRequest("POST", "/api/admin/cms/sections", {
        name: sectionTitle,
        handle: `${handleBase}-${Date.now()}`,
        category: selectedPage.slug || "content",
        isReusable: true,
        blocks: [
          {
            ...selectedSection,
            id: selectedSection.id || `block-${Date.now()}`,
          },
        ],
      });
      return (await response.json()) as CmsSection;
    },
    onSuccess: (section) => {
      if (!section) return;
      updateSelectedSection({
        type: "sectionRef",
        props: {
          sectionId: section.id,
          handle: section.handle,
        },
      });
      queryClient.invalidateQueries({ queryKey: ["/api/admin/cms/sections"] });
      invalidateCmsReadinessQueries();
    },
    onError: (error) => {
      setJsonError(error instanceof Error ? error.message : "Reusable section could not be created.");
    },
  });

